from itertools import product, combinations
import heapq


def _dependency_solver(preference, name_order):
    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        ordered = names if name_order == "ascending" else list(reversed(names))
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        rows_by_name = {}
        for name in names:
            rows_by_name[name] = {}
            for row in packages[name]:
                version = row["version"]
                if version not in blocked.get(name, []) and (name not in pins or pins[name] == version):
                    rows_by_name[name][version] = row

        choices = []
        for name in names:
            choices.append([None] + list(rows_by_name[name]))

        best_vector = None
        best_versions = None
        for assignment in product(*choices):
            selected = {name: version for name, version in zip(names, assignment)
                        if version is not None}
            if any(name not in selected or not bounds[0] <= selected[name] <= bounds[1]
                   for name, bounds in data["roots"].items()):
                continue

            graph = {name: [] for name in selected}
            valid = True
            for name, version in selected.items():
                row = rows_by_name[name][version]
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    target = dep["name"]
                    target_version = selected.get(target)
                    if target_version is None or not dep["min"] <= target_version <= dep["max"]:
                        valid = False
                        break
                    graph[name].append(target)
                if not valid:
                    break
            if not valid:
                continue

            reachable = set()
            stack = list(data["roots"])
            while stack:
                node = stack.pop()
                if node in reachable:
                    continue
                reachable.add(node)
                stack.extend(graph[node])
            if reachable != set(selected):
                continue

            state, cycle = {}, False
            def visit(node):
                nonlocal cycle
                if state.get(node) == 1:
                    cycle = True
                    return
                if state.get(node) == 2:
                    return
                state[node] = 1
                for target in graph[node]:
                    visit(target)
                    if cycle:
                        return
                state[node] = 2
            for node in graph:
                visit(node)
                if cycle:
                    break
            if cycle:
                continue

            vector = tuple(selected.get(name, -1) for name in ordered)
            if best_vector is None or (vector > best_vector if preference == "maximum"
                                       else vector < best_vector):
                best_vector = vector
                best_versions = selected
        return {"versions": best_versions} if best_versions is not None else {"error": "unsatisfiable"}
    return solve


def _ledger(data):
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for position, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        key = (event.get("revision", 0), position)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]
    def rounded(numerator):
        if mode == "half_up":
            return (numerator + 5000) // 10000
        return numerator // 10000

    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount))
        tax = rounded(net * event.get("tax_bp", 0))
        amount = net + tax
        if event.get("kind") == "refund":
            amount = -amount
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + amount
    return {"balances": balances}


def _quota_intervals(data):
    jobs = data["jobs"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    k = data["k"]
    best_value = None
    best_ids = None
    available = [job for job in jobs if job["id"] not in blocked]
    for subset in combinations(available, k):
        ids = sorted(job["id"] for job in subset)
        idset = set(ids)
        if not mandatory.issubset(idset):
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        events = []
        for job in subset:
            events.append((job["start"], 1))
            events.append((job["end"], -1))
        active = 0
        feasible = True
        for _, delta in sorted(events):
            active += delta
            if active > 2:
                feasible = False
                break
        if not feasible:
            continue
        value = sum(job["value"] for job in subset)
        if best_value is None or value > best_value or (value == best_value and ids < best_ids):
            best_value, best_ids = value, ids
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def _temporal_routes(data):
    required = data.get("required", [])
    bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)
    source = data["source"]
    start = data["start"]
    initial_mask = bit.get(source, 0)
    initial = (source, initial_mask, data["coupons"])
    distances = {initial: start}
    queue = [(start, source, initial_mask, data["coupons"])]
    while queue:
        time, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if distances.get(state) != time:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], remaining)]
            if remaining:
                duration = max(2, edge["duration"] - edge.get("discount", 0))
                options.append((duration, remaining - 1))
            for duration, next_remaining in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | bit.get(next_node, 0)
                next_state = (next_node, next_mask, next_remaining)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, next_node, next_mask, next_remaining))
    return {"arrival": None}


SOLVERS = {
    "component_01": _dependency_solver("maximum", "ascending"),
    "component_02": _dependency_solver("minimum", "ascending"),
    "component_03": _dependency_solver("maximum", "descending"),
    "component_04": _dependency_solver("minimum", "descending"),
    "component_05": _dependency_solver("maximum", "ascending"),
    "component_06": _ledger,
    "component_07": _quota_intervals,
    "component_08": _temporal_routes,
}
